17:   vigencias: any[];
18:   vigenciaActual: number;
19:   mostrarTabla: boolean = false;
20:   cargando: boolean = false;
21: 
22:   dataSource: MatTableDataSource<Concepto>;
23: 
24:   @ViewChild(MatPaginator, { static: false }) paginator: MatPaginator;
25:   @ViewChild(MatSort, { static: false }) sort: MatSort;
26: 
27:   displayedColumns: string[] = ['Codigo', 'Nombre', 'Factor', 'Costo'];
28:   nombresColumnas = [];
29: 
30:   constructor(
31:     private translate: TranslateService,
32:     private parametrosService: ParametrosService,
33:     private popUpManager: PopUpManager,
34:     private sgaDerechoPecunarioMidService: SgaDerechoPecunarioMidService
35:   ) {
36:     this.nombresColumnas['Codigo'] = 'derechos_pecuniarios.codigo';
37:     this.nombresColumnas['Nombre'] = 'derechos_pecuniarios.nombre';
38:     this.nombresColumnas['Factor'] = 'derechos_pecuniarios.factor';
39:     this.nombresColumnas['Costo'] = 'derechos_pecuniarios.costo';
40:   }
41: 
42:   ngOnInit() {
43:     this.parametrosService
44:       .get('periodo?query=CodigoAbreviacion:VG&limit=0&sortby=Id&order=desc')
45:       .subscribe(
46:         (response) => {
47:           this.vigencias = response['Data'];
48:         },
49:         () => {
50:           this.popUpManager.showErrorAlert(
51:             this.translate.instant('ERROR.general')
52:           );
53:         }
54:       );
55:   }
56: 
57:   cargarDatos(event: any) {
58:     this.mostrarTabla = false;
59:     this.cargando = true;
60:     this.vigenciaActual = event.value;
61:     let datosCargados = [];
62:     this.mostrarTabla = false;
63:     this.sgaDerechoPecunarioMidService
64:       .get('derechos-pecuniarios/vigencias/' + this.vigenciaActual)
65:       .subscribe(
66:         (response) => {
67:           var data: any[] = response.Data;
68:           if (Object.keys(data).length > 0 && Object.keys(data[0]).length > 0) {
69:             data.forEach((obj) => {
70:               var concepto = new Concepto();
71:               concepto.Id = obj.ParametroId.Id;
72:               concepto.Codigo = obj.ParametroId.CodigoAbreviacion;
73:               concepto.Nombre = obj.ParametroId.Nombre;
74:               concepto.FactorId = obj.Id;
75:               concepto.Factor = JSON.parse(obj.Valor).NumFactor;
76:               if (JSON.parse(obj.Valor).Costo !== undefined) {
77:                 concepto.Costo = JSON.parse(obj.Valor).Costo;
78:               }
79:               datosCargados.push(concepto);
80:             });
81: 
82:             this.dataSource = new MatTableDataSource(datosCargados);
83:             setTimeout(() => {
84:               this.dataSource.paginator = this.paginator;
85:               this.dataSource.sort = this.sort;
86:             }, 100);
87:             this.mostrarTabla = datosCargados.length > 0;
88:           } else {
89:             this.popUpManager.showAlert(
90:               'info',
91:               this.translate.instant('derechos_pecuniarios.no_conceptos')
92:             );
93:           }
94:         },
95:         () => {
96:           this.popUpManager.showErrorAlert(
97:             this.translate.instant('ERROR.general')
98:           );
99:         }
100:       );
101:     this.cargando = false;
102:   }
103: 
104:   formatearPrecio(precio: number): string {
105:     return precio != null
106:       ? precio.toLocaleString('es-CO', { style: 'currency', currency: 'COP' })
107:       : '';
108:   }
109: 
110:   applyFilter(filterValue: string) {
111:     filterValue = filterValue.trim();
112:     filterValue = filterValue.toLowerCase();
113:     this.dataSource.filter = filterValue;
114:   }
115: }

